import os
import google.cloud.translate_v3 as translate

def translate_dictionary_values(payload, config=None):
    config = config or {}
    target_language = config.get("target_language", "en")
    project_id = config.get("project_id", os.getenv("GOOGLE_CLOUD_PROJECT"))

    if not project_id:
        raise ValueError("Google Cloud project ID must be provided in config or GOOGLE_CLOUD_PROJECT environment variable.")

    client = translate.TranslationServiceClient()
    parent = f"projects/{project_id}/locations/global"

    texts_to_translate = []
    original_keys_for_translation = []
    non_string_values = {}

    for key, value in payload.items():
        if isinstance(value, str):
            texts_to_translate.append(value)
            original_keys_for_translation.append(key)
        else:
            non_string_values[key] = value

    if not texts_to_translate:
        return payload

    response = client.translate_text(
        parent=parent,
        contents=texts_to_translate,
        target_language_code=target_language,
        mime_type="text/plain",
    )

    translated_result = {}
    for i, key in enumerate(original_keys_for_translation):
        translated_result[key] = response.translations[i].translated_text

    translated_result.update(non_string_values)
    result = translated_result
    return result
